import unittest

import cli
import importer
import report
from util.text import normalize


class HoldoutTests(unittest.TestCase):
    def test_importer_preserves_the_case_of_names(self):
        self.assertEqual(importer.import_row({"name": "  Acme  Corp ", "qty": "3"}),
                         {"name": "Acme Corp", "qty": 3})

    def test_other_callers_still_lowercase(self):
        self.assertEqual(report.render_title(" Q3 Revenue "), "== q3 revenue ==")
        self.assertEqual(cli.describe(" Hello "), "searching for 'hello'")

    def test_keep_case_still_collapses_whitespace(self):
        self.assertEqual(normalize(" A\t\tB\nC ", keep_case=True), "A B C")

    def test_the_default_is_still_lowercase(self):
        self.assertEqual(normalize("AbC"), "abc")


if __name__ == "__main__":
    unittest.main()
